mapper.update:
UPDATE dms_agent_account
SET total_commission = total_commission + #{amount}
WHERE agent_id = #{agentId}

UPDATE dms_agent_account
SET total_commission = total_commission - #{amount}
WHERE agent_id = #{agentId}

UPDATE dms_agent_account
SET unsettled_commission = unsettled_commission + #{amount}
WHERE agent_id = #{agentId}

UPDATE dms_agent_account
SET unsettled_commission = unsettled_commission - #{amount}
WHERE agent_id = #{agentId}
  AND unsettled_commission >= #{amount}

UPDATE dms_agent_account
SET settled_commission = settled_commission + #{amount}
WHERE agent_id = #{agentId}

UPDATE dms_agent_account
SET settled_commission = settled_commission - #{amount}
WHERE agent_id = #{agentId}

UPDATE dms_agent_account
SET available_balance = available_balance + #{amount}
WHERE agent_id = #{agentId}

UPDATE dms_agent_account
SET available_balance = available_balance - #{amount}
WHERE agent_id = #{agentId}
  AND available_balance >= #{amount}

UPDATE dms_agent_account
SET withdrawn_amount = withdrawn_amount + #{amount}
WHERE agent_id = #{agentId}

UPDATE dms_agent_account
SET total_orders = GREATEST(total_orders + #{count}, 0)
WHERE agent_id = #{agentId}

UPDATE dms_agent_account
SET total_team_members = #{count}
WHERE agent_id = #{agentId}
